using AfriWallet.Compliance.Readiness.Models;
namespace AfriWallet.Compliance.Readiness.Checks;
public sealed class ArchitectureBoundaryCheck:IComplianceReadinessCheck { public string Code=>"CMP-RDY-002";public Task<ReadinessCheck> ExecuteAsync(string root,CancellationToken ct=default){ct.ThrowIfCancellationRequested();var risk=RepositoryCheckUtilities.EnumerateTextFiles(RepositoryCheckUtilities.Resolve(root,"backend","src","Compliance","RiskScoring.Application")).Any();var cases=RepositoryCheckUtilities.EnumerateTextFiles(RepositoryCheckUtilities.Resolve(root,"backend","src","Compliance","CaseManagement.Application")).Any();var ok=risk&&cases;return Task.FromResult(new ReadinessCheck(Code,"Compliance architecture boundaries",ok?ReadinessStatus.Passed:ReadinessStatus.Failed,ok?"Risk scoring and case management layers present":"Required application boundary missing"));} }